def parse_version(s):
    if not s:
        raise ValueError('empty string')
    parts = s.split('.')
    result = []
    for part in parts:
        if part == '':
            raise ValueError('empty component')
        try:
            result.append(int(part))
        except ValueError:
            raise ValueError(f'non-numeric component: {part}')
    return result
